cd /tmp && cat > pclist.go << 'EOF'
package main

import (
	"debug/elf"
	"debug/gosym"
	"encoding/binary"
	"fmt"
	"os"
	"sort"
	"strings"
)

func main() {
	f, err := elf.Open(os.Args[1])
	if err != nil {
		fmt.Fprintf(os.Stderr, "elf: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()

	pclntab := f.Section(".gopclntab")
	if pclntab == nil {
		fmt.Fprintln(os.Stderr, "no .gopclntab")
		os.Exit(1)
	}

	data, err := pclntab.Data()
	if err != nil {
		fmt.Fprintf(os.Stderr, "pclntab read: %v\n", err)
		os.Exit(1)
	}

	fmt.Fprintf(os.Stderr, "pclntab magic: %08x\n", binary.LittleEndian.Uint32(data[:4]))

	var symtab *gosym.Table
	for _, magic := range [][]byte{{0xf1, 0xff, 0xff, 0xff}, {0xfb, 0xff, 0xff, 0xff}, {0xfa, 0xff, 0xff, 0xff}, {0xf0, 0xff, 0xff, 0xff}} {
		copy(data[:4], magic)
		table, e2 := gosym.NewTable(nil, gosym.NewLineTable(data, f.Section(".text").Addr))
		if e2 == nil {
			symtab = table
			fmt.Fprintf(os.Stderr, "parsed with magic %x\n", magic)
			break
		}
	}
	if symtab == nil {
		fmt.Fprintln(os.Stderr, "failed to parse pclntab")
		os.Exit(1)
	}

	// Get all functions
	var fns []string
	for _, fn := range symtab.Funcs {
		if strings.HasPrefix(fn.Name, "main.") {
			fns = append(fns, fmt.Sprintf("%x %s", fn.Entry, fn.Name))
		}
	}
	sort.Strings(fns)
	for _, fn := range fns {
		fmt.Println(fn)
	}
}
EOF
