with open('/input/target', 'rb') as f:
    data = f.read()

def read_str(vma, n=100):
    if 0x6b4000 <= vma < 0x780000:
        foff = vma - 0x6b4000 + 0x2b4000
        end = data.index(b'\x00', foff)
        return data[foff:min(end, foff+n)].decode('utf-8', errors='replace')
    return ''

# The string at 0x74fe31 is 'token must be 16 bytes' and length 0x16 = 22
s = read_str(0x74fe31, 40)
print(f'0x74fe31 ({len(s)} chars): {repr(s)}')
